private int parseEndOfLine(String headerPart, int end) {
    int currentIndex = end;
    boolean carriageReturnFound = false;

    while (currentIndex < headerPart.length()) {
        char currentChar = headerPart.charAt(currentIndex);

        if (currentChar == '\r') {
            carriageReturnFound = true;
            currentIndex++;

            if (currentIndex >= headerPart.length()) {
                break;
            }

            if (headerPart.charAt(currentIndex) == '\n') {
                return currentIndex;
            }
        } else if (currentChar == '\n') {
