public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Initialize variables
    Map<String, Set<String>> adjacencyMap = new HashMap<>();
    Set<String> vertexSet = new HashSet<>();
    List<Pair<String, String>> edges = new ArrayList<>();

    // Iterate through the result map to construct the adjacency map and vertex set
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String vertex = entry.getKey();
        vertexSet.add(vertex);
        Set<String> neighbors = new HashSet<>();
        for (E edge : entry.getValue().getEdges()) {
            neighbors.add(edge.getDestination().getId());
        }
        adjacencyMap.put(vertex, neighbors);
    }

    // Iterate through the adjacency map to construct the edge set
    for (Map.Entry<String, Set<String>> entry : adjacencyMap.entrySet()) {
        String srcVertex = entry.getKey();
        for (String dstVertex : entry.getValue()) {
            edges.add(new Pair<String, String>(srcVertex, dstVertex));
        }
    }

    // Add vertices and edges to the graph
    for (String vertex : vertexSet) {
        target.addVertex(vertex);
    }
    for (Pair<String, String> edge : edges) {
        target.addEdge(edge.getFirst(), edge.getSecond());
    }
}

